package com.bank.monitor;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

// Computes the average and percentiles from a set of request latencies.
public class LatencyStats {
    private final List<Long> latencies = new ArrayList<>();

    public void add(long ms) { latencies.add(ms); }

    // The AVERAGE — dominated by the many fast requests, hides the tail.
    public double average() {
        return latencies.stream().mapToLong(Long::longValue).average().orElse(0);
    }

    // A percentile p (0..1): the latency below which that fraction completes.
    public long percentile(double p) {
        if (latencies.isEmpty()) return 0;
        List<Long> sorted = new ArrayList<>(latencies);
        Collections.sort(sorted);
        int idx = (int) Math.ceil(p * sorted.size()) - 1;
        return sorted.get(Math.max(0, Math.min(idx, sorted.size() - 1)));
    }

    public int count() { return latencies.size(); }
}
