package com.bank.monitor;

import java.util.Random;

// Models a transfer that fans out to N backends and WAITS for all of them.
// The request's latency is the SLOWEST backend — so one slow dependency inflates p99.
public class FanOutModel {
    private final Random rng;
    private final int backends;
    private final double slowChancePerBackend;  // each backend's chance of a slow response
    private final long fastMs;
    private final long slowMs;

    public FanOutModel(long seed, int backends, double slowChancePerBackend,
                       long fastMs, long slowMs) {
        this.rng = new Random(seed);
        this.backends = backends;
        this.slowChancePerBackend = slowChancePerBackend;
        this.fastMs = fastMs;
        this.slowMs = slowMs;
    }

    // Latency of one fan-out request = max over all backends (must wait for the slowest).
    public long requestLatency() {
        long worst = 0;
        for (int b = 0; b < backends; b++) {
            long backendLatency = (rng.nextDouble() < slowChancePerBackend)
                ? slowMs + rng.nextInt(200)     // rare slow backend (e.g. GC pause / cache miss)
                : fastMs + rng.nextInt(30);      // normal fast path
            worst = Math.max(worst, backendLatency);
        }
        return worst;
    }
}
