package com.bank.monitor;

import java.util.logging.*;

// Runnable demo: average looks great, but p99/p99.9 reveal the painful tail.
public class PercentileDemo {
    private static final Logger log = Logger.getLogger(PercentileDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        ch.setLevel(Level.ALL);
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — transfer latency percentiles vs average");

        // Each transfer fans out to 5 backends; each backend has a 1% slow chance.
        FanOutModel model = new FanOutModel(42, 5, 0.01, 40, 1800);
        LatencyStats stats = new LatencyStats();

        int requests = 100_000;
        for (int i = 0; i < requests; i++) stats.add(model.requestLatency());

        double avg = stats.average();
        long p50 = stats.percentile(0.50);
        long p95 = stats.percentile(0.95);
        long p99 = stats.percentile(0.99);
        long p999 = stats.percentile(0.999);

        log.info(() -> String.format("Over %d transfers:", stats.count()));
        log.info(() -> String.format("  AVERAGE = %.1fms  (looks healthy — but hides the tail)", avg));
        log.info(() -> String.format("  p50     = %dms   (typical transfer)", p50));
        log.info(() -> String.format("  p95     = %dms   (1 in 20 slower)", p95));
        log.info(() -> String.format("  p99     = %dms   (1 in 100 slower — fan-out tail!)", p99));
        log.info(() -> String.format("  p99.9   = %dms   (1 in 1000 slower)", p999));

        // SLO check on p99.
        long sloP99Ms = 500;
        if (p99 > sloP99Ms)
            log.severe(() -> "SLO BREACH: p99 " + p99 + "ms > target " + sloP99Ms
                    + "ms — ~" + (requests / 100) + " transfers/window are slow for customers");
        log.info("Note: improving the common path barely moves p99 — the tail is rare GC/"
               + "slow-dependency events, which is why a tight p99 SLO is hard.");
    }
}
